using IdleIntelligence.Runtime;using UnityEngine;using UnityEngine.UI;using UnityEditor;
namespace IdleIntelligence.Editor {
 public static class RepairMainViews {
  public static void Build(){BuildLearning();var root=WorkshopUIFactory.Node("MiraCoach",null);root.AddComponent<LayoutElement>().ignoreLayout=true;var r=(RectTransform)root.transform;r.anchorMin=r.anchorMax=new Vector2(.5f,0);r.pivot=new Vector2(.5f,0);r.anchorMin=new Vector2(0,0);r.anchorMax=new Vector2(1,0);r.anchoredPosition=new Vector2(0,82);r.sizeDelta=new Vector2(-16,240);var coach=root.AddComponent<MiraCoach>();coach.Panel=r;
   var art=WorkshopUIFactory.Node("MiraPortrait",root.transform,typeof(Image)).GetComponent<Image>();art.sprite=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/IdleIntelligence/Art/mira-voss.png");art.preserveAspect=true;art.raycastTarget=false;var ar=art.rectTransform;ar.anchorMin=Vector2.zero;ar.anchorMax=new Vector2(0,1);ar.offsetMin=new Vector2(0,0);ar.offsetMax=new Vector2(78,0);coach.Portrait=art;
   var bubble=WorkshopUIFactory.Vertical("SpeechBubble",root.transform);WorkshopUIFactory.Fill((RectTransform)bubble.transform);((RectTransform)bubble.transform).offsetMin=new Vector2(76,0);var image=bubble.AddComponent<Image>();GameTheme.SurfaceOn(image,GameTheme.Surface);var layout=bubble.GetComponent<VerticalLayoutGroup>();layout.padding=new RectOffset(10,10,8,8);layout.spacing=4;coach.Speaker=WorkshopUIFactory.Label("MiraSpeaker",bubble.transform,"Dr. Mira Voss",14,22);coach.Speaker.font=GameTheme.Bold;coach.Speech=WorkshopUIFactory.Label("StoryDialogue",bubble.transform,"",16,90);coach.Speech.alignment=TextAnchor.UpperLeft;coach.Speech.GetComponent<LayoutElement>().minHeight=coach.Speech.GetComponent<LayoutElement>().preferredHeight=0;coach.Speech.GetComponent<LayoutElement>().flexibleHeight=1;
   var input=WorkshopUIFactory.Node("StoryNameInput",bubble.transform,typeof(Image),typeof(InputField));WorkshopUIFactory.Size(input,44);input.GetComponent<Image>().color=GameTheme.Background;coach.Name=input.GetComponent<InputField>();var text=WorkshopUIFactory.Label("Value",input.transform,"",16);Object.DestroyImmediate(text.GetComponent<LayoutElement>());WorkshopUIFactory.Fill(text.rectTransform);text.rectTransform.offsetMin=new Vector2(8,0);coach.Name.textComponent=text;coach.Name.characterLimit=48;coach.Error=WorkshopUIFactory.Label("StoryNameError",bubble.transform,"",11,16);coach.Confirm=WorkshopUIFactory.Button("StoryChooseName",bubble.transform,"Confirm name",null);
   var actions=WorkshopUIFactory.Horizontal("StoryActions",bubble.transform,44);coach.Confirm.transform.SetParent(actions.transform,false);coach.Skip=WorkshopUIFactory.Button("StorySkipCurrent",actions.transform,"Skip",null);coach.Next=WorkshopUIFactory.Button("StoryContinue",actions.transform,"Continue",null);coach.Target=WorkshopUIFactory.Button("StoryShowTarget",actions.transform,"Show target",null);foreach(var button in new[]{coach.Skip,coach.Next,coach.Target,coach.Confirm}){button.GetComponent<LayoutElement>().minHeight=button.GetComponent<LayoutElement>().preferredHeight=44;button.GetComponentInChildren<Text>().fontSize=13;}PrefabUtility.SaveAsPrefabAsset(root,"Assets/IdleIntelligence/Resources/PixelUI/MiraCoach.prefab");Object.DestroyImmediate(root);AssetDatabase.SaveAssets();}
  static void BuildLearning(){var root=WorkshopUIFactory.Vertical("LearningCard",null);root.AddComponent<Image>();GameTheme.SurfaceOn(root.GetComponent<Image>(),GameTheme.Surface);WorkshopUIFactory.Size(root,204);var layout=root.GetComponent<VerticalLayoutGroup>();layout.padding=new RectOffset(10,10,8,8);layout.spacing=4;layout.childForceExpandHeight=false;var card=root.AddComponent<ActionCard>();card.Button=root.AddComponent<Button>();var view=root.AddComponent<LearningCard>();view.Card=card;
   var header=WorkshopUIFactory.Horizontal("Heading",root.transform,72);header.GetComponent<HorizontalLayoutGroup>().spacing=8;var icon=WorkshopUIFactory.Node("OriginalIcon",header.transform,typeof(Image),typeof(LayoutElement));icon.GetComponent<LayoutElement>().minWidth=icon.GetComponent<LayoutElement>().preferredWidth=48;card.Icon=icon.GetComponent<Image>();card.Icon.preserveAspect=true;card.Icon.raycastTarget=false;var copy=WorkshopUIFactory.Vertical("Copy",header.transform);copy.AddComponent<LayoutElement>().flexibleWidth=1;card.Title=WorkshopUIFactory.Label("NameAndLevel",copy.transform,"",16,24);card.Title.font=GameTheme.Bold;view.Effect=card.Detail=WorkshopUIFactory.Label("CurrentAndNextEffect",copy.transform,"",14,44);view.Effect.alignment=TextAnchor.UpperLeft;
   var costs=WorkshopUIFactory.Horizontal("CostsAndDuration",root.transform,26);costs.GetComponent<HorizontalLayoutGroup>().spacing=8;
   var credit=WorkshopUIFactory.Horizontal("CreditCost",costs.transform,26);view.CreditIcon=CostIcon(credit.transform);view.Credits=WorkshopUIFactory.Label("CreditAmount",credit.transform,"",14,26);var data=WorkshopUIFactory.Horizontal("DataCost",costs.transform,26);view.DataIcon=CostIcon(data.transform);view.Data=WorkshopUIFactory.Label("DataAmount",data.transform,"",14,26);view.Duration=WorkshopUIFactory.Label("Duration",costs.transform,"",14,26);view.Duration.alignment=TextAnchor.MiddleRight;
   view.Requirement=WorkshopUIFactory.Label("Requirement",root.transform,"",13,26);view.Requirement.color=GameTheme.Muted;var actions=WorkshopUIFactory.Horizontal("Actions",root.transform,44);view.Details=WorkshopUIFactory.Button("Details",actions.transform,"Details",null);view.StartAction=WorkshopUIFactory.Button("Start",actions.transform,"Start",null);foreach(var b in new[]{view.Details,view.StartAction}){b.GetComponent<LayoutElement>().minHeight=b.GetComponent<LayoutElement>().preferredHeight=44;}GameTheme.ButtonStyle(view.StartAction,true);view.ActionLabel=view.StartAction.GetComponentInChildren<Text>();view.Progress=WorkshopUIFactory.Node("WorkProgress",root.transform,typeof(Image)).GetComponent<Image>();WorkshopUIFactory.Size(view.Progress.gameObject,4);view.Progress.sprite=GameTheme.Rounded;view.Progress.type=Image.Type.Filled;view.Progress.fillMethod=Image.FillMethod.Horizontal;view.Progress.color=GameTheme.Accent;view.Progress.raycastTarget=false;PrefabUtility.SaveAsPrefabAsset(root,"Assets/IdleIntelligence/Resources/PixelUI/LearningCard.prefab");Object.DestroyImmediate(root);}
  static Image CostIcon(Transform parent){var image=WorkshopUIFactory.Node("ResourceIcon",parent,typeof(Image),typeof(LayoutElement)).GetComponent<Image>();image.GetComponent<LayoutElement>().minWidth=image.GetComponent<LayoutElement>().preferredWidth=20;image.preserveAspect=true;image.raycastTarget=false;return image;}

 }
